package bookstore

// Cost calculates the total cost, in cents, of the given basket of books,
// applying the largest possible discount.
//
// Each book is one of the five titles of the series, identified by the
// integers 1-5. A single copy costs 800 cents. A group of n distinct titles
// is discounted as follows:
//
//	2 titles:  5%  -> 1520
//	3 titles: 10%  -> 2160
//	4 titles: 20%  -> 2560
//	5 titles: 25%  -> 3000
//
// The optimal grouping is to form "layers": round k holds one copy of every
// title that has at least k copies. This uses the largest groups possible,
// which is optimal for this discount schedule except for one case: two groups
// of four (5120) cost less than a group of five plus a group of three (5160).
// So each (5,3) layer pair is replaced by two 4-layers, saving 40 cents each.
func Cost(books []int) int {
	counts := [5]int{}
	for _, b := range books {
		counts[b-1]++
	}

	// price[n] is the cost, in cents, of a group of n distinct titles.
	price := [6]int{0, 800, 1520, 2160, 2560, 3000}

	maxCount := 0
	for _, c := range counts {
		if c > maxCount {
			maxCount = c
		}
	}

	// Walk the layers, summing their cost and counting the 5- and 3-layers.
	base := 0
	five, three := 0, 0
	for k := 1; k <= maxCount; k++ {
		size := 0
		for _, c := range counts {
			if c >= k {
				size++
			}
		}
		base += price[size]
		switch size {
		case 5:
			five++
		case 3:
			three++
		}
	}

	// Replacing a (5,3) layer pair with two 4-layers saves 40 cents.
	if five < three {
		base -= 40 * five
	} else {
		base -= 40 * three
	}

	return base
}

